    const o = {L, vb: gl.createBuffer(), ub: gl.createBuffer(), ib: gl.createBuffer(), tex: gl.createTexture()};
    gl.bindBuffer(gl.ARRAY_BUFFER, o.ub); gl.bufferData(gl.ARRAY_BUFFER, L.uv, gl.STATIC_DRAW);
