function visible(inst){
  const m = inst.box.closest('.modal');
  return inst.box.isConnected && (!m || m.classList.contains('show'));
}
function loop(now){
  if(!INST.size){ rafOn = false; return; }
  INST.forEach(inst => {
    if(!visible(inst)){ inst.dispose(); return; }
    const t = (window.__m25T != null) ? window.__m25T : (now - inst.t0) / 1000;
    const tt = (window.__m25Tap != null) ? window.__m25Tap : (now - (inst.tapAt || -1e9)) / 1000;
    try{ inst.draw(t, tt); }catch(e){ console.warn('res25d', e); inst.fail && inst.fail(); }
  });
  requestAnimationFrame(loop);
}

/* ---------------- ダイアログの 絵を さしかえる ---------------- */
function mount(host){
  if(host.dataset.m25ok) return; host.dataset.m25ok = '1';
  const key = host.dataset.m25, D = DATA[key], img = host.querySelector(':scope > img.rb');
  if(!D || !img) return;
  prepare(key).then(() => {
    if(!host.isConnected) return;
    const box = document.createElement('span'); box.className = 'm25box';
    box.style.cssText = 'position:relative;z-index:1;display:block;flex:none;touch-action:manipulation;' + (img.style.filter ? `filter:${img.style.filter};` : '');
    const cv = document.createElement('canvas'); cv.className = 'm25cv';
    const wp = (D.W + 2 * D.W * D.padX) / D.W * 100, hp = (D.H + D.padT) / D.H * 100;
    cv.style.cssText = `position:absolute;left:${-D.padX * 100}%;bottom:0;width:${wp}%;height:${hp}%;display:block;pointer-events:auto;`;
    box.appendChild(cv);
    /* がぞうの わく（ジャンプで はみだす ぶんの よゆうも ふくめて、もとの 絵と おなじ たかさに おさめる） */
    host.style.display = 'inline-flex'; host.style.flexDirection = 'column'; host.style.justifyContent = 'flex-end';
    const fit = () => {
      const hh = host.clientHeight; if(!hh) return;
      const h = hh * D.H / (D.H + D.padT); box.style.height = h + 'px'; box.style.width = (h * D.W / D.H) + 'px';
    };
    img.replaceWith(box); fit();
    if(window.ResizeObserver){ try{ new ResizeObserver(fit).observe(host); }catch(e){} }
    const inst = makeInst(D, host, box, cv);
    if(!inst){ box.replaceWith(img); return; }
    inst.fail = () => { inst.dispose(); if(box.isConnected) box.replaceWith(img); };
    box.addEventListener('pointerdown', () => { inst.tapAt = performance.now(); });
    INST.add(inst); if(!rafOn){ rafOn = true; requestAnimationFrame(loop); }
  }).catch(e => console.warn('res25d load', e));
}
function scan(root){ (root || document).querySelectorAll('[data-m25]:not([data-m25ok])').forEach(mount); }
const body = document.getElementById('dlgBody');
if(body && window.MutationObserver) new MutationObserver(() => scan(body)).observe(body, {childList:true, subtree:true});

let CTX = null;
const _rp = resPic;
resPic = function(r, cls){
  let h = _rp.apply(this, arguments);
  try{
    if(CTX && !CTX.used && r === CTX.r){
      const k = keyOf(r);
      if(k && document.createElement('canvas').getContext){ CTX.used = true; h = h.replace('class="rpic', `data-m25="${k}" class="rpic`); }
    }
  }catch(e){ console.warn('res25d', e); }
  return h;
};
const _or = openResident;
openResident = function(id){
  try{ const r = save.town.res.find(x => x.id === id); CTX = r ? {r, used:false} : null; }catch(e){ CTX = null; }
  try{ return _or.apply(this, arguments); } finally { CTX = null; }
};
